SELECT d.PIPELINE_DEPENDENCY_ID AS row_id, d.ACTIVE_FLAG AS active_flag, 'Y' AS well_formed, d.PIPELINE_ID AS pipeline_id, d.DEPENDS_ON_PIPELINE_ID AS depends_on_pipeline_id, p.PIPELINE_CODE AS pipeline_code, up.PIPELINE_CODE AS depends_on_pipeline_code, d.DEPENDENCY_TYPE AS dependency_type, d.CONSUME_REPAIRS AS consume_repairs FROM CFG_PIPELINE_DEPENDENCY d JOIN CFG_PIPELINES p ON p.PIPELINE_ID = d.PIPELINE_ID JOIN CFG_PIPELINES up ON up.PIPELINE_ID = d.DEPENDS_ON_PIPELINE_ID ORDER BY 1
